+/** The supported language an Accept-Language header prefers (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string") return fallback;
+  const ranges = [];
+  for (const part of header.split(",")) {
+    const [tag, ...params] = part.split(";").map((p) => p.trim().toLowerCase());
+    if (!tag) continue;
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.*)$/.exec(p);
+      if (m) q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1]) ? Number(m[1]) : 0;
+    }
+    if (q > 0) ranges.push({ tag, q });
+  }
+  ranges.sort((a, b) => b.q - a.q);
+  for (const { tag } of ranges) {
+    if (tag === "*") return fallback;
+    const primary = tag.split("-")[0];
+    if (LANGUAGES.includes(primary)) return primary;
+  }
+  return fallback;
+}
